SELECT i.id, i.project_id, p.project_name, i.issue_no, i.issue_title, i.risk_point, i.auditor_id, u.real_name AS auditor_name, i.status, i.evidence_count, i.create_time FROM audit_issue i LEFT JOIN audit_project p ON p.id = i.project_id AND p.deleted = 0 LEFT JOIN sys_user u ON u.id = i.auditor_id AND u.deleted = 0
i.deleted = 0
AND i.project_id = #{q.projectId}
AND i.status = #{q.status}
AND i.auditor_id = #{q.auditorId}
AND (i.issue_title LIKE CONCAT('%', #{q.keyword}, '%') OR i.issue_no LIKE CONCAT('%', #{q.keyword}, '%'))
ORDER BY i.create_time DESC

SELECT MAX(issue_no)
FROM audit_issue
WHERE project_id = #{projectId}
